export function getSubCategoryEditorial(
  path: string,
  cleanName: string,
  displayTitle: string,
  categoryName: string
): SubCategoryEditorialData {
  if (subcategoryEditorialMap[path]) {
    return subcategoryEditorialMap[path];
  }
  return getDefaultSubCategoryEditorial(path, cleanName, displayTitle, categoryName);
}
